// 多指标：每条序列各自用给定值播种滚动缓冲
var stream = new ArcRealtimeStream
{
    Series = new[]
    {
        new ChartSeries("p95", new double[] { 182, 176, 191, 204, 188, 172, 165, 179, 212, 196, 184, 178 }),
        new ChartSeries("p50", new double[] { 92, 88, 95, 101, 94, 87, 84, 90, 104, 98, 93, 89 })
    },
    WindowSize = 36,
    Interval = TimeSpan.FromMilliseconds(500),
    ValueSuffix = " ms"
};

// 单指标：Values 是 Series 的快捷入口
var single = new ArcRealtimeStream
{
    Values = new double[] { 182, 176, 191, 204, 188, 172 },
    IsLive = false
};
